import {loadMotion,showMotion,motionEnabled,setMotion} from './motion.mjs?v=7';
import {gameView,gameInput,inGame,setGameNavigation} from './game-ui.mjs?v=12';
import {SwipeGate,SceneState} from './engine.mjs?v=8';
import {weatherPose} from './game.mjs?v=10';
import {defaultScenes,restoreScenes,artworkIndex,weatherPhase,weatherSceneIndex} from './scenes.mjs?v=11';
const $=id=>document.getElementById(id);
let scenes=defaultScenes();
let state=new SceneState(scenes.length),gate=new SwipeGate(),db,stream,tracker,raf,loading=false,lastFrame=-1,lastDetect=0,held=null,poseArmed=true,releaseSince=null;
const removedScenes=[];
const urls=new Map();const url=v=>{if(typeof v==='string')return v;if(!urls.has(v))urls.set(v,URL.createObjectURL(v));return urls.get(v)};
function feedback(s){$('status').textContent=s}
async function initDB(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('dragon-gesture-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('project');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const saved=await new Promise((resolve,reject)=>{const r=db.transaction('project').objectStore('project').get('scenes');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});scenes=restoreScenes(saved);state.count=scenes.length;state.index=Math.min(state.index,scenes.length-1);render()}catch{$('saveStatus').textContent='Browser storage unavailable. Changes last only until this tab closes.'}}
function save(){if(!db)return;const tx=db.transaction('project','readwrite');tx.objectStore('project').put(scenes,'scenes');tx.oncomplete=()=>$('saveStatus').textContent='Saved on this device.';tx.onerror=()=>$('saveStatus').textContent='Storage is full. Changes work now but may not survive closing this tab.'}
function resetGesture(){gate.reset();held=null;poseArmed=false;releaseSince=null}
function render(){const s=scenes[state.index];$('scene').src=url(s.image);const mi=artworkIndex(s),phase=weatherPhase(s);showMotion(mi,phase>=0);gameView(phase>=0,phase);$('sceneName').textContent=s.name;$('name').value=s.name;$('gesture').value=s.gesture;$('counter').textContent=`SCENE ${String(state.index+1).padStart(2,'0')} / ${String(scenes.length).padStart(2,'0')}`;$('mode').textContent=state.busy?'TRANSITION PLAYING':state.index===scenes.length-1?'FINAL SCENE':'READY TO EXPLORE';$('back').disabled=state.busy||state.index===0;$('next').disabled=state.busy||inGame()||state.index===scenes.length-1;$('next').textContent=state.index===scenes.length-1?'Presentation complete':'Next scene →';$('clipInfo').textContent=s.clip?'Transition video attached. It plays once before the next scene.':'Built-in animated transition. Add a video here to override it.';$('playGame').disabled=state.busy||![0,1,2].some(p=>weatherSceneIndex(scenes,p)>=0);$('removeScene').disabled=state.busy||scenes.length<=1;$('undoRemove').hidden=!removedScenes.length;$('undoRemove').disabled=state.busy;for(const id of ['name','gesture','imageFile','videoFile','removeClip','add'])$(id).disabled=state.busy;$('strip').replaceChildren(...scenes.map((s,i)=>{const b=document.createElement('button');b.className='thumb'+(i===state.index?' active':'');b.disabled=state.busy;const im=document.createElement('img');im.src=url(s.image);im.alt=s.name;const text=document.createElement('span');text.textContent=String(i+1).padStart(2,'0')+' · '+s.name;b.append(im,text);b.onclick=()=>jump(i);return b}));$('stagehint').textContent=state.busy?'Playing transition…':state.index===scenes.length-1?'End of presentation':s.gesture==='swipe'?'Small swipe left · or press →':s.gesture==='manual'?'Press → to continue':`Hold ${s.gesture} fingers · or press →`}
function jump(i){if(state.busy)return;state.index=i;resetGesture();render()}
async function cloudWipe(){const c=$('cloud');await c.animate([{transform:'translateX(110%)'},{transform:'translateX(0%)'}],{duration:650,easing:'ease-in',fill:'forwards'}).finished;$('scene').src=url(scenes[state.index+1].image);const target=scenes[state.index+1];const mi=artworkIndex(target),phase=weatherPhase(target);showMotion(mi,phase>=0);gameView(phase>=0,phase);await c.animate([{transform:'translateX(0%)'},{transform:'translateX(-110%)'}],{duration:700,easing:'ease-out',fill:'forwards'}).finished;c.getAnimations().forEach(a=>a.cancel())}
async function playClip(blob){const v=$('transition');v.src=url(blob);v.style.display='block';v.controls=true;return new Promise((resolve,reject)=>{let timer=setTimeout(()=>finish(new Error('Video took too long to load.')),15000);function finish(e){clearTimeout(timer);v.onended=v.onerror=v.onplaying=null;v.pause();v.style.display='none';v.removeAttribute('src');v.load();e?reject(e):resolve()}v.onplaying=()=>clearTimeout(timer);v.onended=()=>finish();v.onerror=()=>finish(new Error('This video cannot be played. Try exporting MP4 from Canva.'));v.play().catch(e=>finish(e))})}
async function next(){if(inGame()||!state.begin())return;resetGesture();render();try{const clip=scenes[state.index].clip;if(clip)await playClip(clip);else {await cloudWipe();}state.complete();feedback(stream?'Scene ready. Lower your hand, then make a new gesture.':'Scene ready. Enable the camera to try hand control.')}catch(e){state.cancel();feedback('Transition stopped: '+e.message)}resetGesture();render()}
$('next').onclick=next;$('back').onclick=()=>jump(Math.max(0,state.index-1));$('present').onclick=()=>$('stage').requestFullscreen().catch(()=>feedback('Full screen is unavailable in this browser.'));document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.repeat)return;if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();next()}if(e.key==='ArrowLeft')jump(Math.max(0,state.index-1))});$('name').onchange=()=>{scenes[state.index].name=$('name').value.trim()||'Untitled scene';save();render()};$('gesture').onchange=()=>{scenes[state.index].gesture=$('gesture').value;resetGesture();save();render()};
async function attach(id,type){const f=$(id).files[0];if(!f)return;if(f.size>150*1024*1024){feedback('Choose a file smaller than 150 MB.');return}try{if(type==='image'){const im=new Image();im.src=URL.createObjectURL(f);try{await im.decode()}finally{URL.revokeObjectURL(im.src)}}else{if(!document.createElement('video').canPlayType(f.type)){throw new Error('Please use an MP4 or WebM video supported by your browser.')}}scenes[state.index][type==='image'?'image':'clip']=f;save();render()}catch(e){feedback('Could not add file. '+e.message)}$(id).value=''}$('imageFile').onchange=()=>attach('imageFile','image');$('videoFile').onchange=()=>attach('videoFile','video');$('removeClip').onclick=()=>{scenes[state.index].clip=null;save();render()};$('add').onclick=()=>{scenes.push({name:'New scene',image:scenes[state.index].image,gesture:'swipe',clip:null});state.count=scenes.length;jump(scenes.length-1);save()};
$('removeScene').onclick=()=>{
 if(state.busy||scenes.length<=1)return;
 const index=state.index;gameView(false);removedScenes.push({index,scene:scenes[index]});
 const [removed]=scenes.splice(index,1);state.count=scenes.length;jump(Math.min(index,scenes.length-1));save();
 $('sceneEditStatus').textContent=`Removed “${removed.name}”. You can undo this before closing or refreshing the page.`;
};
$('undoRemove').onclick=()=>{
 if(state.busy||!removedScenes.length)return;
 gameView(false);const {index,scene}=removedScenes.pop(),position=Math.min(index,scenes.length);
 scenes.splice(position,0,scene);state.count=scenes.length;jump(position);save();
 $('sceneEditStatus').textContent=`Restored “${scene.name}”.`;
};
function countFingers(l){const d=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);let n=[8,12,16,20].filter(t=>d(l[t],l[0])>d(l[t-2],l[0])*1.18).length;if(d(l[4],l[17])>d(l[3],l[17])*1.15)n++;return n}
function stopCamera(){cancelAnimationFrame(raf);stream?.getTracks().forEach(t=>t.stop());stream=null;$('camera').srcObject=null;$('overlay').getContext('2d').clearRect(0,0,640,480);$('cameraPlaceholder').style.display='grid';$('start').textContent='Enable camera';resetGesture();feedback('Camera is off. Use Next scene or the arrow keys.')}
$('start').onclick=async()=>{if(stream){stopCamera();return}if(loading)return;loading=true;$('start').disabled=true;feedback('Loading hand tracking…');try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Open this page in Chrome or Edge using the website link.');if(!tracker){const {HandLandmarker,FilesetResolver}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const vision=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');tracker=await HandLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'VIDEO',numHands:1,minHandDetectionConfidence:.5,minHandPresenceConfidence:.5,minTrackingConfidence:.5})}stream=await navigator.mediaDevices.getUserMedia({video:{width:640,height:480,facingMode:'user'},audio:false});$('camera').srcObject=stream;await $('camera').play();$('cameraPlaceholder').style.display='none';$('start').textContent='Stop camera';lastFrame=-1;resetGesture();feedback('Camera ready. Pause briefly, then make a small left swipe in the preview.');raf=requestAnimationFrame(tick)}catch(e){stopCamera();feedback(e.name==='NotAllowedError'?'Camera permission was denied. Allow camera access in your browser, then try again.':'Camera could not start: '+e.message+' You can still use Next scene.')}finally{loading=false;$('start').disabled=false}};
function tick(t){if(!stream)return;const v=$('camera');if(v.readyState>=2&&v.currentTime!==lastFrame&&t-lastDetect>40){lastFrame=v.currentTime;lastDetect=t;try{const r=tracker.detectForVideo(v,t),l=r.landmarks[0],ctx=$('overlay').getContext('2d');ctx.clearRect(0,0,640,480);if(l){ctx.fillStyle='#5cf0c1';for(const p of l){ctx.beginPath();ctx.arc(p.x*640,p.y*480,4,0,Math.PI*2);ctx.fill()}}const s=scenes[state.index];if(inGame()){const n=l?countFingers(l):-1;gameInput(weatherPose(n),l?(weatherPhase(s)===1?1-[0,5,9,13,17].reduce((sum,i)=>sum+l[i].x,0)/5:1-l[0].x):null,t);if(!state.busy)feedback(l?'Hand found — follow the current game challenge.':'Show one hand to play the weather game.')}else if(s.gesture==='swipe'){const p=l?{x:1-[0,5,9,13,17].reduce((sum,i)=>sum+l[i].x,0)/5,y:[0,5,9,13,17].reduce((sum,i)=>sum+l[i].y,0)/5}:null;if(gate.update(p?.x,p?.y,t,state.busy))next();else if(!state.busy)feedback(l?(gate.armed?'Ready — swipe left in the preview.':'Hand found — hold still briefly.'):'Show one hand to the camera.')}else if(s.gesture!=='manual'&&!state.busy){const n=l?countFingers(l):0,target=Number(s.gesture);if(n!==target){held=null;if(releaseSince===null)releaseSince=t;if(t-releaseSince>500)poseArmed=true}else{releaseSince=null;if(poseArmed){if(held===null)held=t;if(t-held>800){poseArmed=false;held=null;next()}}}feedback(`Detected ${n} fingers. ${poseArmed?'Hold '+target+' fingers to continue.':'Lower your hand to reset.'}`)}}catch(e){stopCamera();feedback('Hand tracking stopped. Try enabling the camera again.')}}raf=requestAnimationFrame(tick)}
function jumpToWeather(phase){for(let p=phase;p<=3;p++){const i=weatherSceneIndex(scenes,p);if(i>=0){jump(i);return}}jump(0)}
$('playGame').onclick=()=>jumpToWeather(0);setGameNavigation(jumpToWeather,()=>jump(0));$('motionToggle').onclick=()=>setMotion(!motionEnabled());
window.addEventListener('pagehide',stopCamera);render();initDB();loadMotion().then(()=>{render();setMotion(motionEnabled())}).catch(()=>feedback('Animated artwork could not load. Reload the page to retry; still scenes remain available.'));